-- New local arena state only; preserve all existing player data.
CREATE TABLE public.player_arena_states (
    player_id TEXT NOT NULL REFERENCES public.players(player_id) ON DELETE CASCADE,
    arena_code BIGINT NOT NULL,
    rank INTEGER NOT NULL DEFAULT 0 CHECK (rank >= 0),
    challenge_count BIGINT NOT NULL CHECK (challenge_count >= 0),
    challenge_day BIGINT NOT NULL,
    cool_time_end_at BIGINT NOT NULL DEFAULT 0 CHECK (cool_time_end_at >= 0),
    time_reward_count INTEGER NOT NULL DEFAULT 0 CHECK (time_reward_count >= 0),
    PRIMARY KEY (player_id, arena_code)
);
